{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_unconverted():
    assert conversion_rate([session("a", 1, True), session("b", 1, None),
                            session("c", 1, False)]) == 1 / 3
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_handles_empty_groups():
    groups = {"a": [session("a", 1, True)],
              "b": [session("b", 1, False), session("c", 1, None),
                    session("d", 1, False)], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (5, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_log_flags_whitespace_and_skipped_lines():
    lines = ["\n", "  # comment, with commas\n", "  a  ,  2 , 1  \n",
             "b, -3, 0", "c, 4,   ", " \t "]
    assert parse_session_log(iter(lines)) == [session("a", 2, True),
                                              session("b", -3, False),
                                              session("c", 4, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,nope,1", "a,1,yes"])
def test_parse_log_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log([" # comment", " ", bad_line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    first = session("a", 1, True)
    last = session("a", 3, None)
    events = [first, session("z", 1, False), session("b", 3, True), last,
              session("c", 3, False)]
    assert dedupe_sessions(events) == [events[1], last, events[2], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_gaps_and_ignore_outside_range():
    events = [session("a", 0, True), session("b", 1, True),
              session("c", 1, True), session("d", 2, None),
              session("e", 3, False), session("f", 4, True)]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_counts_calendar_days_and_nonempty_groups():
    groups = {"one": [session("a", 1, True)],
              "two": [session("b", 4, False), session("c", 5, True)],
              "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 10)["recent"] == 2
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_order_ties_and_exclude_empty():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_rates_by_group_include_empty_and_sort_names():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 1.0, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]


def test_longest_streak_requires_consecutive_positive_counts():
    assert longest_conversion_streak([1, 1, 0, 2, -1, 3, 4, 5]) == 3
    assert longest_conversion_streak([-1, 0, -2]) == 0
    assert longest_conversion_streak([]) == 0
